"""QQ-Lora分组加载（仅模型）：多组 LoRA 各自配好，一次只让选中的那组生效。

每个分组有自己的名字和一组 LoRA（名称 + 强度），按列表顺序依次叠加到 MODEL 上。
面板里点分组即切换生效组，开关关掉时模型原样透传。

另外留了两个可选输入口，方便接 ``QQ-多值输入`` 当外部参数：

============  ==================================================
``启用开关``  覆盖面板上的开关（真/假、1/0、启用/停用都认）
``生效分组``  覆盖面板选中的分组：填 1 起的序号或分组名字
============  ==================================================

它们没接线时用面板上的设置；接线后用外部值，面板仍显示当前选择，方便对照。
"""

from __future__ import annotations

import json
from typing import Any

MAX_GROUPS = 64
MAX_LORAS_PER_GROUP = 64
DEFAULT_GROUP_NAME = "分组"
DEFAULT_STRENGTH = 1.0

#: 面板写入的 JSON 版本号，将来改结构时用来做兼容。
DATA_VERSION = 1


def _empty_data() -> dict[str, Any]:
    return {"version": DATA_VERSION, "active": 0, "groups": []}


def _clamp_strength(value: Any) -> float:
    try:
        strength = float(value)
    except (TypeError, ValueError):
        return DEFAULT_STRENGTH
    if strength != strength or strength in (float("inf"), float("-inf")):
        return DEFAULT_STRENGTH
    return round(max(-100.0, min(100.0, strength)), 4)


def _clean_name(value: Any, fallback: str) -> str:
    name = str(value or "").strip().replace("\n", " ")
    return name[:60] or fallback


def normalise_data(raw: Any) -> dict[str, Any]:
    """把面板存的 JSON 收敛成可用结构；坏数据一律退回空分组表。"""
    data: Any = raw
    if isinstance(raw, str):
        try:
            data = json.loads(raw or "{}")
        except (TypeError, ValueError):
            return _empty_data()
    if not isinstance(data, dict):
        return _empty_data()

    groups: list[dict[str, Any]] = []
    for index, entry in enumerate(data.get("groups") or []):
        if not isinstance(entry, dict):
            continue
        name = _clean_name(entry.get("name"), f"{DEFAULT_GROUP_NAME} {index + 1}")
        loras: list[dict[str, Any]] = []
        for item in entry.get("loras") or []:
            if not isinstance(item, dict):
                continue
            lora_name = str(item.get("name") or "").strip()
            if not lora_name:
                continue
            loras.append({"name": lora_name, "strength": _clamp_strength(item.get("strength"))})
            if len(loras) >= MAX_LORAS_PER_GROUP:
                break
        groups.append({"name": name, "loras": loras})
        if len(groups) >= MAX_GROUPS:
            break

    try:
        active = int(data.get("active") or 0)
    except (TypeError, ValueError):
        active = 0
    if groups:
        active = max(0, min(len(groups) - 1, active))
    else:
        active = 0
    return {"version": DATA_VERSION, "active": active, "groups": groups}


def coerce_enabled(value: Any, default: bool = True) -> bool:
    """把开关值（布尔 / 数字 / 文字）统一成布尔；认不出时用面板上的值。"""
    if value is None:
        return bool(default)
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    text = str(value).strip().lower()
    if not text:
        return bool(default)
    if text in {"1", "true", "yes", "on", "启用", "开启", "是", "开"}:
        return True
    if text in {"0", "false", "no", "off", "停用", "关闭", "否", "关"}:
        return False
    return bool(default)


def resolve_group(data: dict[str, Any], override: Any = None) -> dict[str, Any] | None:
    """选出这次生效的分组；``override`` 支持 1 起的序号或分组名字。

    ``override`` 给了但对不上任何分组时，退回面板当前选中的那一组。
    """
    groups = data.get("groups") or []
    if not groups:
        return None
    text = "" if override is None else str(override).strip()
    if text:
        lowered = text.lower()
        for index, group in enumerate(groups):
            if str(index + 1) == text or str(group.get("name") or "").lower() == lowered:
                return group
        # 序号写法容错：「第2组」「2组」
        digits = "".join(char for char in text if char.isdigit())
        if digits:
            try:
                index = int(digits) - 1
            except ValueError:
                index = -1
            if 0 <= index < len(groups):
                return groups[index]
        # 外部值指向了不存在的分组（比如那一组被删了）：退回面板当前选择，
        # 不要静默地一个 Lora 都不加载。
        index = int(data.get("active") or 0)
        if index < 0 or index >= len(groups):
            index = 0
        return groups[index]
    index = int(data.get("active") or 0)
    if index < 0 or index >= len(groups):
        index = 0
    return groups[index]


def plan_loras(
    data: dict[str, Any],
    enabled: bool,
    override: Any = None,
) -> list[tuple[str, float]]:
    """这次要依次应用的 (lora 名称, 强度)；关掉或没选到分组时为空。"""
    if not enabled:
        return []
    group = resolve_group(data, override)
    if not group:
        return []
    return [
        (entry["name"], entry["strength"])
        for entry in group.get("loras") or []
        if entry.get("name") and entry.get("strength") != 0
    ]


class QQLoraGroupLoader:
    CATEGORY = "QQ/工具"
    FUNCTION = "load"
    RETURN_TYPES = ("MODEL",)
    RETURN_NAMES = ("模型",)
    DESCRIPTION = (
        "多组 LoRA 分别配好，每次只让选中的那一组生效；每组可选多个 LoRA 并单独设强度，"
        "按列表顺序依次叠加到模型上。关掉开关则原样透传模型。"
        "可选输入「启用开关」「生效分组」可以接 QQ-多值输入 之类的节点做外部控制。"
    )

    def __init__(self) -> None:
        self._loaded: dict[str, tuple[Any, Any]] = {}

    @classmethod
    def INPUT_TYPES(cls) -> dict[str, Any]:
        return {
            "required": {
                "model": ("MODEL",),
                # 由面板开关写入，界面上隐藏
                "启用": ("BOOLEAN", {"default": True, "label_on": "启用", "label_off": "停用"}),
                # 面板维护的分组数据（JSON），界面上隐藏
                "分组数据": ("STRING", {"default": "{}", "multiline": False}),
                # 外部控制的值：前端把 QQ-多值输入 这类虚拟节点的值抄进来，
                # 界面上隐藏。虚拟节点不会进 prompt，接线本身带不来值。
                "外部开关": ("STRING", {"default": "", "multiline": False}),
                "外部分组": ("STRING", {"default": "", "multiline": False}),
            },
            "optional": {
                # 接多值输入：外部指定启用状态 / 哪个分组生效
                "启用开关": ("STRING", {"forceInput": True}),
                "生效分组": ("STRING", {"forceInput": True}),
            },
        }

    @classmethod
    def VALIDATE_INPUTS(cls, **kwargs: Any) -> bool:
        # 分组数据随面板变化，旧工作流里可能存着已删除的分组，不能硬校验
        return True

    def _load_lora(self, name: str) -> tuple[Any, Any]:
        import comfy.utils
        import folder_paths

        path = folder_paths.get_full_path_or_raise("loras", name)
        cached = self._loaded.get(path)
        if cached is not None:
            return cached
        lora, metadata = comfy.utils.load_torch_file(path, safe_load=True, return_metadata=True)
        # 和核心 LoraLoader 一样只留最近一个，避免一堆大文件常驻内存
        self._loaded = {path: (lora, metadata)}
        return lora, metadata

    def load(
        self,
        model: Any,
        启用: bool = True,
        分组数据: str = "{}",
        外部开关: str = "",
        外部分组: str = "",
        启用开关: Any = None,
        生效分组: Any = None,
    ):
        data = normalise_data(分组数据)
        # 真节点连线优先；接线接的是虚拟节点时由前端把值抄进「外部开关」等隐藏控件
        switch = 启用开关 if 启用开关 not in (None, "") else 外部开关
        enabled = coerce_enabled(switch, default=bool(启用))
        group_override = 生效分组 if 生效分组 not in (None, "") else (外部分组 or None)
        plan = plan_loras(data, enabled, group_override)
        if not plan:
            return (model,)

        import comfy.sd

        result = model
        for name, strength in plan:
            try:
                lora, metadata = self._load_lora(name)
                result, _clip = comfy.sd.load_lora_for_models(
                    result, None, lora, strength, 0, lora_metadata=metadata
                )
            except Exception as err:  # 单个 LoRA 坏了不拖垮整条链，报出名字继续
                print(f"[QQ-Lora分组加载] 跳过 {name}：{err}", flush=True)
        return (result,)


NODE_CLASS_MAPPINGS = {"QQLoraGroupLoader": QQLoraGroupLoader}
NODE_DISPLAY_NAME_MAPPINGS = {"QQLoraGroupLoader": "QQ-Lora分组加载"}
